const fs = require('fs');
const zlib = require('zlib');
const path = '/workspace/testbed/docs/customer_report.docx';
const buf = fs.readFileSync(path);

// docx is a zip - parse it manually
// ZIP local file headers start with PK\x03\x04
let offset = 0;
const files = [];
while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) === 0x04034b50) {
    const fnLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const fn = buf.slice(offset + 30, offset + 30 + fnLen).toString('utf8');
    const dataStart = offset + 30 + fnLen + extraLen;
    const rawData = buf.slice(dataStart, dataStart + compSize);
    files.push({ fn, compMethod, rawData, compSize, uncompSize });
    offset = dataStart + compSize;
  } else {
    break;
  }
}

// Find word/document.xml
for (const f of files) {
  if (f.fn === 'word/document.xml') {
    let xml;
    if (f.compMethod === 8) {
      xml = zlib.inflateRawSync(f.rawData).toString('utf8');
    } else {
      xml = f.rawData.toString('utf8');
    }
    // Extract text from <w:t> tags
    const matches = xml.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
    let currentPara = '';
    let lastIdx = 0;
    // Better: split by paragraph
    const paras = xml.split(/<\/w:p>/);
    for (const p of paras) {
      const texts = [];
      const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
      let m;
      while ((m = re.exec(p)) !== null) {
        texts.push(m[1]);
      }
      if (texts.length > 0) {
        console.log(texts.join(''));
      }
    }
    break;
  }
}

// Also check for tables
for (const f of files) {
  if (f.fn === 'word/document.xml') {
    let xml;
    if (f.compMethod === 8) {
      xml = zlib.inflateRawSync(f.rawData).toString('utf8');
    } else {
      xml = f.rawData.toString('utf8');
    }
    // Check for tables
    if (xml.includes('<w:tbl>') || xml.includes('<w:tbl ')) {
      console.log('\n--- Tables detected, extracting rows ---');
      const tableRe = /<w:tbl[\s>][\s\S]*?<\/w:tbl>/g;
      let tm;
      while ((tm = tableRe.exec(xml)) !== null) {
        const tableXml = tm[0];
        const rows = tableXml.split(/<\/w:tr>/);
        for (const row of rows) {
          const cells = row.split(/<\/w:tc>/);
          const cellTexts = [];
          for (const cell of cells) {
            const txts = [];
            const re2 = /<w:t[^>]*>([^<]*)<\/w:t>/g;
            let m2;
            while ((m2 = re2.exec(cell)) !== null) {
              txts.push(m2[1]);
            }
            if (txts.length > 0) cellTexts.push(txts.join(''));
          }
          if (cellTexts.length > 0) console.log(cellTexts.join(' | '));
        }
        console.log();
      }
    }
    break;
  }
}
